parts.text:
{
  "units": [
    {
      "quote": "(3) Authorization required: Marketing.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Serves as the heading designating the subject matter of the subsection regarding marketing authorizations and contains no operative legal rule."
    },
    {
      "quote": "other than the transition provisions in § 164.532",
      "scope_quotes": [
        "Notwithstanding any provision of this subpart,"
      ],
      "kind": "exception",
      "meaning": "Exempts the transition provisions in § 164.532 from being overridden by the marketing authorization requirement."
    },
    {
      "quote": "a covered entity must obtain an authorization for any use or disclosure of protected health information for marketing",
      "scope_quotes": [
        "Notwithstanding any provision of this subpart, other than the transition provisions in § 164.532,",
        "except if the communication is in the form of:"
      ],
      "kind": "requirement",
      "meaning": "A covered entity must obtain an authorization for any use or disclosure of protected health information for marketing, notwithstanding any other provision of this subpart (except § 164.532 transition provisions), unless an enumerated exception applies."
    },
    {
      "quote": "A face-to-face communication made by a covered entity to an individual",
      "scope_quotes": [
        "Notwithstanding any provision of this subpart, other than the transition provisions in § 164.532, a covered entity must obtain an authorization for any use or disclosure of protected health information for marketing, except if the communication is in the form of:"
      ],
      "kind": "exception",
      "meaning": "A covered entity is not required to obtain an authorization for marketing if the communication is in the form of a face-to-face communication made by the covered entity to an individual."
    },
    {
      "quote": "A promotional gift of nominal value provided by the covered entity.",
      "scope_quotes": [
        "Notwithstanding any provision of this subpart, other than the transition provisions in § 164.532, a covered entity must obtain an authorization for any use or disclosure of protected health information for marketing, except if the communication is in the form of:"
      ],
      "kind": "exception",
      "meaning": "A covered entity is not required to obtain an authorization for marketing if the communication is in the form of a promotional gift of nominal value provided by the covered entity."
    },
    {
      "quote": "nominal value",
      "scope_quotes": [
        "A promotional gift of nominal value provided by the covered entity.",
        "except if the communication is in the form of:"
      ],
      "kind": "threshold",
      "meaning": "To qualify for the promotional gift exception from the marketing authorization requirement, the value of the gift provided by the covered entity must not exceed a nominal amount."
    },
    {
      "quote": "If the marketing involves financial remuneration, as defined in paragraph (3) of the definition of marketing at § 164.501, to the covered entity from a third party,",
      "scope_quotes": [],
      "kind": "condition",
      "meaning": "Sets the condition triggering a specific disclosure mandate in the authorization, applying whenever marketing involves financial remuneration to the covered entity from a third party as defined in paragraph (3) of § 164.501."
    },
    {
      "quote": "the authorization must state that such remuneration is involved.",
      "scope_quotes": [
        "If the marketing involves financial remuneration, as defined in paragraph (3) of the definition of marketing at § 164.501, to the covered entity from a third party,"
      ],
      "kind": "requirement",
      "meaning": "When marketing involves financial remuneration (defined in paragraph (3) of § 164.501) to the covered entity from a third party, the authorization must explicitly state that such remuneration is involved."
    }
  ]
}
